// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
  spring,
  Img,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type ChurchLifeTransitionProps = Record<string, any>;

const ChurchLifeTransition: React.FC<ChurchLifeTransitionProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 5,
  primaryGradientStart = "#0a192f",
  primaryGradientEnd = "#4a148c",
  sweepColorWhite = "#ffffff",
  sweepColorGold = "#ffb300",
  accentGreen = "#00e676",
  accentBlue = "#2979ff",
  accentRed = "#ff1744",
  accentPurple = "#d500f9",
  logo = "https://upload.wikimedia.org/wikipedia/commons/8/85/Circle-icons-star.svg",
  title = "Malloy Studio",
  subtitle = "Live Broadcast",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = durationInSeconds * fps;
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  const ltWidth = width * 0.6;
  const ltHeight = height * 0.18;

  const startX = -width;
  const endX = width;

  // Intro Springs (Staggered to create a leading edge)
  const introGoldVal = spring({ fps, frame, config: { damping: 14 } });
  const introWhiteVal = spring({ fps, frame: frame - 3, config: { damping: 14 } });
  const introMainVal = spring({ fps, frame: frame - 6, config: { damping: 14 } });

  // Outro Springs (Staggered to create a trailing edge)
  const outroStartFrame = totalFrames - fps;
  const outroMainVal = spring({ fps, frame: frame - outroStartFrame, config: { damping: 14 } });
  const outroWhiteVal = spring({ fps, frame: frame - (outroStartFrame + 3), config: { damping: 14 } });
  const outroGoldVal = spring({ fps, frame: frame - (outroStartFrame + 6), config: { damping: 14 } });

  // Combined X Positions
  const goldX =
    interpolate(introGoldVal, [0, 1], [startX, 0]) +
    interpolate(outroGoldVal, [0, 1], [0, endX]);

  const whiteX =
    interpolate(introWhiteVal, [0, 1], [startX, 0]) +
    interpolate(outroWhiteVal, [0, 1], [0, endX]);

  const mainX =
    interpolate(introMainVal, [0, 1], [startX, 0]) +
    interpolate(outroMainVal, [0, 1], [0, endX]);

  // Sweep progression while lower third is fully on screen
  const holdProgress = interpolate(frame, [fps, totalFrames - fps], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const sharedLayerStyle: React.CSSProperties = {
    position: "absolute",
    left: 0,
    top: 0,
    height: "100%",
    transformOrigin: "bottom left",
    transition: "none",
  };

  const accents = [
    { color: accentGreen, size: height * 0.03, relX: width * 0.02, y: -0.2, p: 0.05, layer: "bg" },
    { color: accentBlue, size: height * 0.04, relX: width * 0.15, y: 1.2, p: -0.02, layer: "fg" },
    { color: accentRed, size: height * 0.02, relX: width * 0.3, y: -0.1, p: 0.03, layer: "bg" },
    { color: accentPurple, size: height * 0.05, relX: width * 0.45, y: 1.1, p: -0.04, layer: "fg" },
    { color: sweepColorGold, size: height * 0.025, relX: width * 0.55, y: -0.3, p: 0.06, layer: "bg" },
  ];

  const renderAccents = (layerType: string) => {
    return accents
      .filter((a) => a.layer === layerType)
      .map((a, i) => {
        // Tie accents to mainX so they slide in with the graphic
        const px = mainX * (1 + a.p) + a.relX;
        const py = a.y * ltHeight + Math.sin((frame + i * 10) / 15) * (ltHeight * 0.15);
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              width: a.size,
              height: a.size,
              borderRadius: "50%",
              backgroundColor: a.color,
              transform: `translate(${px}px, ${py}px)`,
              boxShadow: `0 0 ${height * 0.02}px ${a.color}80`,
              opacity: 0.9,
              transition: "none",
            }}
          />
        );
      });
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden", transition: "none" }}>
      {/* Lower Third Wrapper */}
      <div
        style={{
          position: "absolute",
          left: width * 0.1,
          bottom: height * 0.15,
          width: ltWidth,
          height: ltHeight,
          transition: "none",
        }}
      >
        {/* Background Accents */}
        {renderAccents("bg")}

        {/* Gold Layer (Lowest, widest) */}
        <div
          style={{
            ...sharedLayerStyle,
            width: "104%",
            backgroundColor: sweepColorGold,
            transform: `translateX(${goldX}px) skewX(-25deg)`,
            boxShadow: `0 0 ${width * 0.02}px ${sweepColorGold}80`,
          }}
        />

        {/* White Layer */}
        <div
          style={{
            ...sharedLayerStyle,
            width: "102%",
            backgroundColor: sweepColorWhite,
            transform: `translateX(${whiteX}px) skewX(-25deg)`,
            boxShadow: `0 0 ${width * 0.01}px ${sweepColorWhite}80`,
          }}
        />

        {/* Main Gradient Cover */}
        <div
          style={{
            ...sharedLayerStyle,
            width: "100%",
            background: `linear-gradient(90deg, ${primaryGradientStart}, ${primaryGradientEnd})`,
            transform: `translateX(${mainX}px) skewX(-25deg)`,
            boxShadow: `0 0 ${width * 0.02}px rgba(0,0,0,0.5)`,
            overflow: "hidden",
          }}
        >
          {/* Internal soft sweep (left to right) */}
          <div
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              height: "100%",
              width: "40%",
              background: "linear-gradient(90deg, transparent, rgba(255,255,255,0.15), transparent)",
              transform: `translateX(${interpolate(holdProgress, [0, 1], [-ltWidth, ltWidth])}px)`,
              transition: "none",
            }}
          />
          {/* Internal soft sweep (right to left counter-sweep) */}
          <div
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              height: "100%",
              width: "20%",
              background: "linear-gradient(90deg, transparent, rgba(255,255,255,0.1), transparent)",
              transform: `translateX(${interpolate(holdProgress, [0, 1], [ltWidth, -ltWidth])}px)`,
              transition: "none",
            }}
          />
        </div>

        {/* Content Wrapper (Unskewed, synced to Main block) */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: "100%",
            height: "100%",
            transform: `translateX(${mainX}px)`,
            display: "flex",
            alignItems: "center",
            padding: `0 ${width * 0.08}px 0 ${width * 0.04}px`, // Right padding extra for skew
            boxSizing: "border-box",
            gap: width * 0.02,
            transition: "none",
          }}
        >
          {logo && (
            <Img
              src={logo}
              style={{
                height: "65%",
                width: "auto",
                objectFit: "contain",
                filter: "drop-shadow(0px 4px 10px rgba(0,0,0,0.3))",
              }}
            />
          )}
          <div style={{ display: "flex", flexDirection: "column", justifyContent: "center" }}>
            {title && (
              <div
                style={{
                  fontSize: height * 0.05,
                  fontWeight: 800,
                  color: "#ffffff",
                  fontFamily: spaceGroteskFamily,
                  textShadow: "0 2px 10px rgba(0,0,0,0.5)",
                  lineHeight: 1.1,
                  whiteSpace: "nowrap",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                }}
              >
                {title}
              </div>
            )}
            {subtitle && (
              <div
                style={{
                  fontSize: height * 0.03,
                  fontWeight: 500,
                  color: "#e0e0e0",
                  fontFamily: interFamily,
                  textShadow: "0 2px 10px rgba(0,0,0,0.5)",
                  lineHeight: 1.1,
                  whiteSpace: "nowrap",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                }}
              >
                {subtitle}
              </div>
            )}
          </div>
        </div>

        {/* Foreground Accents */}
        {renderAccents("fg")}
      </div>
    </AbsoluteFill>
  );
};

export default ChurchLifeTransition;